FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 090: mate connectors by axis points, loop centres, a virtual sharp, a cone tip and a sphere centre; an aligned section of a composite. Generated by tools/fixtures/gen-batch-090.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function roundVector(v is Vector) returns Vector
{
    return vector(round(v[0] * 1e6) / 1e6, round(v[1] * 1e6) / 1e6, round(v[2] * 1e6) / 1e6);
}

// A mate connector's coordinate system, rounded so it compares as text.
function connectorFrame(context is Context, connector is Query) returns map
{
    const cs = evMateConnector(context, { "mateConnector" : connector });
    return { "origin" : roundVector(cs.origin / millimeter), "x" : roundVector(cs.xAxis), "z" : roundVector(cs.zAxis) };
}

// mate-connector: the top of a cylinder's axis (radius 10, z 0 to 30)
export function c001(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(baseSketch, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 30 * millimeter });
    mateConnector(context, id + "mc1", { "originQuery" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(10, 0, 15) * millimeter), "entityInferenceType" : EntityInferenceType.TOP_AXIS_POINT, "ownerPart" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID) });
    return { "frame" : connectorFrame(context, qCreatedBy(id + "mc1", EntityType.BODY)) };
}

