    const n1 = newSketchOnPlane(context, id + "n1", { "sketchPlane" : plane(vector(0, 0, 10) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(n1, "l1", { "start" : vector(20, 15) * millimeter, "end" : vector(40, 15) * millimeter });
