    skLineSegment(n1, "l3", { "start" : vector(40, 30) * millimeter, "end" : vector(20, 30) * millimeter });
    skLineSegment(n1, "l4", { "start" : vector(20, 30) * millimeter, "end" : vector(20, 15) * millimeter });
